<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emberline — 黄昏铸造厂战术 FPS</title>
<style>
  :root { --accent: #f97316; --amber: #ffb347; --teal: #59b8c4; --red: #ff3b30; }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #14100f;
    font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; color: #f2ede8; }
  #game { display: block; width: 100vw; height: 100vh; }
  .hidden { display: none !important; }
  #hud { position: fixed; inset: 0; pointer-events: none; z-index: 5; }

  /* Crosshair: four lines whose gap follows the live spread. */
  #crosshair { position: absolute; left: 50%; top: 50%; width: 0; height: 0; --gap: 8px; }
  #crosshair .cl { position: absolute; background: rgba(255,255,255,0.95); box-shadow: 0 0 2px #000; }
  #crosshair .t { left: -1px; top: calc(-1 * var(--gap) - 8px); width: 2px; height: 8px; }
  #crosshair .b { left: -1px; top: var(--gap); width: 2px; height: 8px; }
  #crosshair .l { top: -1px; left: calc(-1 * var(--gap) - 8px); width: 8px; height: 2px; }
  #crosshair .r { top: -1px; left: var(--gap); width: 8px; height: 2px; }
  #crosshair .dot { left: -1.5px; top: -1.5px; width: 3px; height: 3px; border-radius: 50%; }
  #hitmarker { position: absolute; left: 50%; top: 50%; width: 26px; height: 26px;
    margin: -13px 0 0 -13px; opacity: 0; transition: opacity 0.12s; }
  #hitmarker::before, #hitmarker::after { content: ""; position: absolute; left: 12px; top: 0;
    width: 2px; height: 26px; background: #fff; }
  #hitmarker::before { transform: rotate(45deg); }
  #hitmarker::after { transform: rotate(-45deg); }
  #hitmarker.crit::before, #hitmarker.crit::after { background: var(--red); }

  /* Bottom-left: health + weapon. */
  #bl { position: absolute; left: 22px; bottom: 20px; }
  #health-num { font-size: 44px; font-weight: 800; line-height: 1; text-shadow: 0 2px 6px #000; }
  #health-bar-wrap { width: 220px; height: 8px; background: rgba(0,0,0,0.55); margin-top: 6px; border: 1px solid rgba(255,255,255,0.25); }
