  #ammo { position: absolute; right: 22px; bottom: 20px; text-align: right; }
  #ammo-mag { font-size: 44px; font-weight: 800; line-height: 1; text-shadow: 0 2px 6px #000; }
  #ammo-res { font-size: 18px; color: #cfc8c0; }
  #grenades { margin-top: 6px; font-size: 14px; color: #e8ddd2; text-shadow: 0 1px 4px #000; }
  #kevlar { color: var(--teal); font-weight: 700; }

  /* Top centre: timer + score. */
  #top { position: absolute; left: 50%; top: 14px; transform: translateX(-50%); text-align: center; }
  #score-line { font-size: 24px; font-weight: 800; text-shadow: 0 2px 6px #000; }
  #score-ember { color: var(--accent); }
  #score-ash { color: var(--teal); }
  #timer { font-size: 20px; font-weight: 700; margin-top: 2px; text-shadow: 0 2px 6px #000; }
  #round-label { font-size: 12px; color: #d8cfc6; text-shadow: 0 1px 4px #000; }
  #pips { font-size: 13px; letter-spacing: 2px; margin-top: 2px; text-shadow: 0 1px 4px #000; }
  #pips-ember { color: var(--accent); }
  #pips-ash { color: var(--teal); }
  #money { position: absolute; left: 22px; top: 14px; font-size: 22px; font-weight: 800;
