  /* Minimap top-right. */
  #minimap { position: absolute; right: 22px; top: 14px; border: 1px solid rgba(255,255,255,0.3);
    background: rgba(20,24,30,0.85); }

  /* Killfeed + radio, left under the money. */
  #killfeed { position: absolute; left: 22px; top: 52px; font-size: 14px; line-height: 1.7; }
  .feed-ember { color: #ffb37a; text-shadow: 0 1px 3px #000; }
  .feed-ash { color: #9fd8de; text-shadow: 0 1px 3px #000; }
  .feed-sys { color: #e8ddd2; text-shadow: 0 1px 3px #000; }
  #radio { position: absolute; left: 22px; bottom: 150px; font-size: 13px; color: #ffd9ae;
    line-height: 1.7; text-shadow: 0 1px 3px #000; }
  #bomb-status { position: absolute; left: 50%; top: 108px; transform: translateX(-50%);
    font-size: 15px; font-weight: 700; color: var(--amber); text-shadow: 0 1px 4px #000; }

  /* Plant progress. */
  #plant-bar { position: absolute; left: 50%; top: 58%; transform: translateX(-50%);
    width: 260px; height: 10px; background: rgba(0,0,0,0.6); border: 1px solid var(--amber); }
  #plant-fill { height: 100%; width: 0%; background: var(--amber); }

  /* Round banner. */
  #banner { position: absolute; left: 50%; top: 30%; transform: translateX(-50%); text-align: center; }
  #banner-title { font-size: 52px; font-weight: 900; letter-spacing: 4px; text-shadow: 0 3px 12px #000; }
  #banner-sub { font-size: 18px; margin-top: 6px; text-shadow: 0 2px 6px #000; }

  /* Damage numbers + flashes. */
  #dmg-layer { position: absolute; inset: 0; overflow: hidden; }
  .dmg { position: absolute; font-size: 18px; font-weight: 800; color: #fff;
    text-shadow: 0 1px 4px #000; transform: translate(-50%, -50%); }
  .dmg.crit { color: var(--red); font-size: 22px; }
  #damage-flash { position: absolute; inset: 0; background: radial-gradient(ellipse at center,
    transparent 55%, rgba(255,40,30,0.55) 100%); opacity: 0; transition: opacity 0.15s; }

  /* Buy menu. */
  #buy-menu { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
    width: 460px; background: rgba(16,18,22,0.92); border: 1px solid var(--accent);
    padding: 18px 20px; }
  #buy-menu h2 { font-size: 20px; color: var(--accent); margin-bottom: 4px; }
  #buy-menu p { font-size: 13px; color: #cfc8c0; margin-bottom: 12px; }
  .buy-item { display: flex; gap: 10px; padding: 7px 8px; font-size: 15px; border-bottom: 1px solid rgba(255,255,255,0.08); }
  .buy-key { color: var(--amber); font-weight: 800; width: 18px; }
  .buy-label { flex: 1; }
  .buy-price { color: var(--amber); font-weight: 700; }
  .buy-item.owned { opacity: 0.55; }
  .buy-item.poor .buy-price { color: var(--red); }

  /* Overlays. */
  .overlay { position: fixed; inset: 0; z-index: 10; display: flex; flex-direction: column;
    align-items: center; justify-content: center; background: rgba(12,8,10,0.82);
    cursor: pointer; text-align: center; padding: 20px; }
  .overlay h1 { font-size: 64px; font-weight: 900; letter-spacing: 6px; color: var(--accent);
    text-shadow: 0 4px 24px rgba(249,115,22,0.5); }
  .overlay h2 { font-size: 18px; font-weight: 400; color: #e8ddd2; margin-top: 10px; line-height: 1.8; }
  .overlay .cta { margin-top: 26px; font-size: 20px; font-weight: 800; color: #fff;
    border: 2px solid var(--accent); padding: 12px 34px; }
  .overlay .fine { margin-top: 18px; font-size: 13px; color: #a99e94; line-height: 1.8; }
  #hint { position: absolute; left: 50%; bottom: 8px; transform: translateX(-50%);
    font-size: 12px; color: #b8ada2; text-shadow: 0 1px 3px #000; white-space: nowrap; }
</style>
